python3 << 'PY'
xs = [-100,-80,-60,-40,-20,0,20,40,60,80,100]
p1 = [0,0,7,15,28,33,29,15,5,4,0]
p2 = [0,3,9,18,30,36,28,20,8,2,0]
ys = [(a+b)/2 for a,b in zip(p1,p2)]

def profile(x, scale=1.0):
    if x <= xs[0] or x >= xs[-1]:
        return 0.0
    for i in range(len(xs)-1):
        if xs[i] <= x <= xs[i+1]:
            t = (x - xs[i]) / (xs[i+1]-xs[i])
            return scale*((ys[i]*(1-t) + ys[i+1]*t))
    return 0.0

# base scale matching pitch 34 -> 88 at flow 200
def interior_mean(pitch, scale):
    n = 80
    vals = [sum(profile(pitch*i/n - k*pitch, scale) for k in range(-30,31)) for i in range(n)]
    return sum(vals)/len(vals)

base = 88/interior_mean(34, 1)
print("base scale", base)

def lines_for(margin, pitch, mode):
    y0, y1 = -margin, 500+margin
    if mode == 'start':
        ys_l = []
        y = y0
        while y <= y1 + 1e-6:
            ys_l.append(y)
            y += pitch
        return ys_l
    if mode == 'center_inset':
        # lines inset half pitch from bounds, step pitch, stop before exceeding
        ys_l = []
        y = y0 + pitch/2
        while y <= y1 + 1e-6:
            ys_l.append(y)
            y += pitch
        return ys_l
    if mode == 'inclusive_ends':
        span = y1 - y0
        n = max(1, round(span / pitch))
        return [y0 + k*span/n for k in range(n+1)]
    if mode == 'ceil_span':
        span = y1 - y0
        import math
        n = math.ceil(span / pitch)
        # n gaps, n+1 lines from y0 to y1
        return [y0 + k*span/n for k in range(n+1)]

def dft_at(yq, lines, scale):
    return sum(profile(yq - ly, scale) for ly in lines)

for pitch, margin in [(50, 40), (50, 50), (50, 60), (45, 40), (60, 50), (34, 40)]:
    flow_factor = 88/interior_mean(pitch, base)  # relative to flow 200
    scale = base * flow_factor
    print(f"\n==== pitch {pitch} margin {margin} flow {200*flow_factor:.0f} at speed 400 (scale {scale:.3f}) ====")
    for mode in ['start', 'center_inset', 'inclusive_ends', 'ceil_span']:
        lines = lines_for(margin, pitch, mode)
        pts = [0, 10, 30, 250, 470, 490, 500]
        vals = [dft_at(y, lines, scale) for y in pts]
        print(f"  {mode:16} n={len(lines):2} first={lines[0]:7.1f} last={lines[-1]:7.1f} DFT {list(zip(pts, [round(v,1) for v in vals]))}")
PY

